<?php
use App\Domain\Industries\{IndustryDependencyInspector,IndustryManager,IndustryRelationManager};use App\Models\{Industry,IndustryCategory,NavigationItem,NavigationMenu,Product,Solution,User,WebsiteSetting};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;use function Pest\Laravel\mock;uses(RefreshDatabase::class);function industryAdmin():User{return User::factory()->create(['is_active'=>true]);}function industriesInstalled():void{mock(\App\Domain\Installation\InstalledState::class)->shouldReceive('isInstalled')->andReturnTrue();}
it('protects industry administration create and preview routes',function(){industriesInstalled();$industry=Industry::factory()->create();$this->get(route('admin.industries.index'))->assertRedirect('/login');$this->get(route('admin.industries.create'))->assertRedirect('/login');$this->get(route('admin.industries.preview',$industry))->assertRedirect('/login');});
it('requires an active administrator',function(){industriesInstalled();$this->actingAs(User::factory()->create(['is_active'=>false]))->get(route('admin.industries.index'))->assertForbidden();});
it('allows anonymous index and only visible details',function(){$draft=Industry::factory()->create();$future=Industry::factory()->scheduled()->create();$due=Industry::factory()->scheduled(now()->subMinute())->create();$published=Industry::factory()->published()->create();$archived=Industry::factory()->archived()->create();$this->get(route('industries.index'))->assertSuccessful();$this->get(route('industries.show',$draft->slug))->assertNotFound();$this->get(route('industries.show',$future->slug))->assertNotFound();$this->get(route('industries.show',$due->slug))->assertSuccessful();$this->get(route('industries.show',$published->slug))->assertSuccessful();$this->get(route('industries.show',$archived->slug))->assertNotFound();});
it('normalizes slugs and rejects unsafe fields and arbitrary presentation',function(){industriesInstalled();$this->actingAs(industryAdmin())->post(route('admin.industries.store'),['title'=>'Public Sector','slug'=>'Public Sector','short_description'=>'Configured summary','template'=>'standard','hero_style'=>'standard'])->assertRedirect();$this->assertDatabaseHas('industries',['slug'=>'public-sector','status'=>'draft']);$this->post(route('admin.industries.store'),['title'=>'Bad','slug'=>'create','short_description'=>'Summary','template'=>'blade','hero_style'=>'unknown','featured_image_path'=>'https://remote.test/a.jpg','featured_image_alt'=>'A','primary_cta_label'=>'Run','primary_cta_url'=>'javascript:alert(1)'])->assertSessionHasErrors(['slug','template','hero_style','featured_image_path','primary_cta_url']);});
it('creates unique ordered categories',function(){industriesInstalled();$this->actingAs(industryAdmin())->post(route('admin.industries.categories.store'),['name'=>'Government','slug'=>'Government','is_active'=>1])->assertRedirect();$this->post(route('admin.industries.categories.store'),['name'=>'Duplicate','slug'=>'government'])->assertSessionHasErrors('slug');expect(IndustryCategory::first()->display_order)->toBe(1);});
it('enforces structured child maximum and icon allow list',function(){industriesInstalled();$industry=Industry::factory()->create();for($i=1;$i<=12;$i++){$industry->challenges()->create(['title'=>"Challenge $i",'description'=>'Configured factual text','display_order'=>$i]);}$this->actingAs(industryAdmin())->post(route('admin.industries.children.store',[$industry,'challenges']),['title'=>'Overflow','description'=>'Text'])->assertSessionHasErrors('challenges');$industry->outcomes()->create(['title'=>'Outcome','description'=>'Configured outcome','display_order'=>1]);$this->post(route('admin.industries.children.store',[$industry,'needs']),['title'=>'Need','description'=>'Text','icon'=>'<svg>'])->assertSessionHasErrors('icon');});
it('enforces relation limits and archived targets',function(){$industry=Industry::factory()->create();$archived=Product::factory()->archived()->create();expect(fn()=>app(IndustryRelationManager::class)->sync($industry,[],[$archived->id],[]))->toThrow(ValidationException::class);$solutions=Solution::factory()->count(9)->create()->pluck('id')->all();expect(fn()=>app(IndustryRelationManager::class)->sync($industry,$solutions,[],[]))->toThrow(ValidationException::class);});
it('performs lifecycle scheduling duplication and safe preview',function(){industriesInstalled();$admin=industryAdmin();WebsiteSetting::create(['singleton_key'=>1,'site_name'=>'Naxora','site_url'=>'https://example.test','timezone'=>'Africa/Lagos']);$industry=Industry::factory()->create(['overview'=>'Preserved']);$industry->challenges()->create(['title'=>'Configured','description'=>'Text','display_order'=>1]);$manager=app(IndustryManager::class);$manager->publish($industry);expect($industry->refresh()->status)->toBe('published');$manager->unpublish($industry);expect($industry->refresh()->overview)->toBe('Preserved');$manager->schedule($industry,'2026-08-07 12:00:00');$copy=$manager->duplicate($industry,$admin->id);expect($copy->status)->toBe('draft')->and($copy->slug)->not->toBe($industry->slug)->and($copy->challenges)->toHaveCount(1)->and($copy->scheduled_for)->toBeNull();$this->actingAs($admin)->get(route('admin.industries.preview',$industry))->assertSuccessful()->assertSee('Preview Mode')->assertHeader('X-Robots-Tag','noindex, nofollow')->assertHeader('Cache-Control','no-store, private, max-age=0');});
it('blocks archive for active navigation references',function(){$industry=Industry::factory()->create();$menu=NavigationMenu::create(['name'=>'Primary','location'=>'primary','is_active'=>true]);NavigationItem::create(['navigation_menu_id'=>$menu->id,'label'=>'Industry','link_type'=>'industry','industry_id'=>$industry->id,'target'=>'_self','display_order'=>1,'depth'=>1,'is_active'=>true]);expect(app(IndustryDependencyInspector::class)->inspect($industry)['blocked'])->toBeTrue();expect(fn()=>app(IndustryManager::class)->archive($industry))->toThrow(ValidationException::class);});
it('includes indexable industries in sitemap without private or fabricated claims',function(){$public=Industry::factory()->published()->create();$private=Industry::factory()->create();$this->get(route('sitemap'))->assertSuccessful()->assertSee('/industries/'.$public->slug,false)->assertDontSee('/industries/'.$private->slug,false);$this->get(route('industries.show',$public->slug))->assertSuccessful()->assertDontSee('customer count')->assertDontSee('request_token')->assertDontSee('signed_entitlement');});
